import sys
sys.path.insert(0, str(__import__("pathlib").Path(__file__).resolve().parents[1]))
from pathlib import Path
from collections import defaultdict,Counter
from backend.communication.technologies import DEFAULT_TECHNOLOGY_REGISTRY as registry
p=Path('README.md');s=p.read_text(encoding='utf-8')
s=s.replace('Der universelle Simulationskern unterstützt jede integrierte oder\nbenutzerdefinierte Bus-Technologie. Für CAN und Ethernet stehen zusätzlich\nnative Writer zur Verfügung.', 'Die zentrale TechnologyProfile-Registry beschreibt integrierte und\nbenutzerdefinierte Verbindungstypen. Parameterprüfung, ausführbares\nKapazitätsmodell und native Dateiausgabe sind getrennte Fähigkeiten; ein\nregistriertes Profil allein belegt keine vollständige Simulation. Für CAN\nund Ethernet stehen technologieabhängige native Writer zur Verfügung.')
profiles=registry.profiles();groups=defaultdict(list)
for profile in profiles: groups[profile['layer']].append(profile.get('label') or profile['id'])
labels={'PHYSICAL':'Physikalische Verbindungen','DATA_LINK':'Bus- und Sicherungsschichten','NETWORK':'Netzwerkschichten','TRANSPORT':'Transportschichten','APPLICATION':'Anwendungsprotokolle','INDUSTRY_PROFILE':'Anwendungsprofile'}
lines=['## Unterstützte Verbindungstypen und Technologien','',f'Die zentrale Registry enthält **{len(profiles)} einzeln geprüfte Technologieprofile**.','Die folgende Liste wird nach Protokollschicht gegliedert. Branchen beeinflussen','Empfehlungen und Vorlagen, begrenzen aber nicht die Technologieauswahl.','Ein gemischtes Projekt führt Parameter und Nachweise je Technologie, Netz und','Geräteanschluss getrennt. Ethernet wird beispielsweise nicht als NMEA-2000-','oder I²C-Verbindung bewertet.','']
for layer in ['PHYSICAL','DATA_LINK','NETWORK','TRANSPORT','APPLICATION','INDUSTRY_PROFILE']:
 if groups[layer]: lines += [f"- **{labels[layer]}:** "+', '.join(groups[layer])+'.']
lines+=['','### Parameter, Standardvorschläge und Nachweise','','- Wizard, Parametereditor und API verwenden das profilgebundene Schema. Die','  Technologieauswahl bietet eine Suche über den vollständigen Katalog.','- Literaturwerte werden als überprüfbare Vorschläge angeboten. Bedingte Werte','  gelten nur bei passender Betriebsart, Version und Gerätekonfiguration; bei','  I²C ist Standard-mode mit 100 kbit/s der bekannte Basismodus. Es werden','  weder fremde CAN-Werte noch eine erfundene Gerätefrequenz eingesetzt.','- Ein vorhandener bestätigter Wert bleibt erhalten. Geräteadresse, tatsächliche','  Verkabelung, Clock-Stretching, Arbitration, Transaktionsumfang, Security und','  gemessene Verzögerungen brauchen eigene Quellen und Bestätigung.','- Große ganzzahlige Protokollwerte werden im Browser als Dezimaltext verlustfrei','  gespeichert; die Python-Prüfung berechnet sie als exakte Ganzzahlen.','- Bestätigung einer Busfrequenz ist kein Kapazitätsnachweis. Kapazität und','  Schedule werden getrennt von funktionaler Deadline, Datenalter und','  Fehlerreaktion geprüft. I²C unterscheidet Controller-Port, Target-Port und','  Transaktion; ein Controller-Port benötigt keine erfundene Slave-Adresse.','','### Ausführbarer Umfang','','| Fähigkeit | Bedeutung |','|---|---|','| Profil und Parameterprüfung | Literatur- und implementierungsbezogene Felder, Grenzen und Abhängigkeiten; keine Hardwarezertifizierung. |','| `MODEL_AVAILABLE` | Ein registriertes Kapazitätsmodell existiert; Berechnung setzt den tatsächlichen, vollständigen und bestätigten Projekt-Nachweis voraus. |','| `MODEL_MISSING` | Profil kann ausgewählt und geprüft werden; Kapazität oder vollständige Protokollausführung wird als fehlend gemeldet. Es gibt keinen Ersatz durch CAN oder Ethernet. |','| `NOT_APPLICABLE` | Direkte I/O-Verbindung; kein Buslastmodell. Geräte-, Prozess- und Funktionsnachweise bleiben erforderlich. |','| `PARTIAL` / `EXPERIMENTAL` | Umfang des integrierten Modells; keine Aussage über Reife oder Normkonformität der Bus-Technologie selbst. |','','Kapazitätsmodelle sind registriert für: '+', '.join(p.get('label') or p['id'] for p in profiles if (p.get('capacity_evidence') or {}).get('status')=='MODEL_AVAILABLE')+'.','Direkte I/O-Verbindungen ohne Buslastmodell: '+', '.join(p.get('label') or p['id'] for p in profiles if (p.get('capacity_evidence') or {}).get('status')=='NOT_APPLICABLE')+'.','Alle anderen hier aufgeführten Profile bleiben ohne ausführbaren','Kapazitätsnachweis `MODEL_MISSING`. Beispiele sind Matter, M-Bus, Wireless','M-Bus, WirelessHART, MIL-STD-1553, WTB, XCP und Zigbee. Ihre überprüften','Parameter und Mechanismen installieren keinen PHY-, Security- oder Schedule-','Executor und ersetzen keine Geräte- oder Systemzertifizierung.','','Benutzerdefinierte Technologiepakete ergänzen die Registry mit geprüften','Beschreibungen und Parameterschemata. Sie installieren keinen ausführbaren','Kapazitätscode; ihr Kapazitätsstatus bleibt `MODEL_MISSING`.','','Quellen, einzelne Parameterentscheidungen und Tests:','[Prüfprotokoll aller Technologieprofile](docs/implementation-workloads/technology-full-parameter-audit-20261001/progress.json).','Die Einzelprüfungen beziehen sich auf die dort dokumentierten Quellen,','Editionen und Implementierungen; sie behaupten keine vollständige Zertifizierung','aller optionalen Normteile.','','Native Dateiformate sind technologieabhängig. Ein neutraler JSONL-/CSV-Trace','ist eine gemeinsame Darstellung und beweist keine native Bus-Ausführung.','','| Bereich | Native Formate |','|---|---|','| CAN/CAN FD | BLF, DBC, ASC, TRC, CSV, JSON, XML, YAML, ARXML, FIBEX |','| CAN XL | universeller Trace; CAN-FD-kompatible BLF-Ausgabe bildet keine native CAN-XL-Datei |','| Ethernet/IP-basierte Technologien | PCAP und PCAPNG im jeweils implementierten Writer-Umfang |','| Messdaten | optional MDF und MF4 |','| andere Technologien | neutraler JSONL-/CSV-Trace im ausführbaren Modellumfang |','','### Verifizierte Produktivübernahme','','`python scripts/release-and-deploy.py` prüft den vollständigen Release-Gate','mit isolierter SQL-Datenbank und temporärer Laufzeit. Es übernimmt ausschließlich','das exakt getestete Image aus einem vollständigen PASS-Nachweis und prüft','danach Image-Identität und Betriebsbereitschaft. Ein Neustart eines alten Images','ist keine Übernahme von Codeänderungen. Historische Images werden ohne','dokumentierten Aufbewahrungsnachweis nicht gelöscht.','']
start=s.index('## Unterstützte Technologien');end=s.index('## Installation',start)
s=s[:start]+'\n'.join(lines)+'\n'+s[end:]
p.write_text(s,encoding='utf-8')
print({'profiles':len(profiles),'capacity':Counter((p.get('capacity_evidence') or {}).get('status') for p in profiles)})
